def paragraph(doc, text, style=None):
    return doc.add_paragraph(text, style)


def make(index, item):
    title, issue, question, facts, options, recommendation, checks, form, sources = item
    doc = Document()
    section = doc.sections[0]
    section.page_height = Cm(29.7)
    section.page_width = Cm(21)
    section.top_margin = section.bottom_margin = Cm(1.7)
    section.left_margin = section.right_margin = Cm(2)
    normal = doc.styles['Normal']
    normal.font.name = 'DejaVu Sans'
    normal.font.size = Pt(10.5)
    normal.paragraph_format.space_after = Pt(6)
    normal.paragraph_format.line_spacing = 1.08
    for name in ('Heading 1', 'Heading 2'):
        st = doc.styles[name]
        st.font.name = 'DejaVu Sans'
        st.font.color.rgb = RGBColor.from_string('16324F')
        st.font.size = Pt(17 if name == 'Heading 1' else 12)
    lang = OxmlElement('w:lang')
    lang.set(qn('w:val'), 'ru-RU')
    normal.element.get_or_add_rPr().append(lang)
    head = section.header.paragraphs[0]
    head.text = f'ПОДГОТОВКА К ПРИЁМКЕ  •  РЕШЕНИЕ {index:02d}'
    head.style = doc.styles['Caption']
    doc.add_heading(title, 1)
    issue_label = '№' + issue if issue[0].isdigit() else issue
    paragraph(doc, f'Задача: {issue_label}   |   Сведения на {10 if 2 <= index <= 5 else 9} сентября 2026 года')
    paragraph(doc, 'Решение об обязательном исправлении принято пользователем 10.09.2026. Независимая приёмка выполнения ожидается.' if 2 <= index <= 5 else 'Пояснительная записка. Решение ещё не принято. Номер документа служит только для навигации и не заменяет обозначения требований проекта.')
    doc.add_heading('Что нужно решить', 2)
    paragraph(doc, question)
    doc.add_heading('Что известно сейчас', 2)
    paragraph(doc, facts)
    doc.add_heading('Принятое решение' if 2 <= index <= 5 else 'Варианты решения', 2)
    for text in options:
        paragraph(doc, text, 'List Bullet')
    doc.add_heading('На что опираться при выборе', 2)
    paragraph(doc, recommendation)
    doc.add_page_break()
    doc.add_heading('Проверка и запись решения', 1)
    paragraph(doc, title)
    doc.add_heading('Что проверить перед подписанием', 2)
    for text in checks:
        paragraph(doc, '☐ ' + text)
    doc.add_heading('Кто принимает и где записать', 2)
    who = 'Руководитель совместной работы назначает независимого проверяющего.' if index == 1 else 'Решение принимает назначенный специалист, независимый от автора принимаемого результата; окончательный контрольный рубеж оформляет координатор на основании этих решений.'
    paragraph(doc, who + ' Заключение сохраняется в обсуждении соответствующей задачи или изменения с точной ссылкой на проверенные файлы. Подписанный документ можно приложить к этой записи.')
    doc.add_heading('Бланк заключения', 2)
    paragraph(doc, form)
    paragraph(doc, 'Проверяющий: ____________________    Дата: ____________________')
    paragraph(doc, 'Проверенная версия и файлы: __________________________________')
    paragraph(doc, 'Основания решения и ссылки: __________________________________')
    paragraph(doc, 'Если нужна доработка: действие, ответственный, способ проверки: ______')
    doc.add_heading('Материалы для проверки', 2)
    issue_match = __import__('re').match(r'\d+', issue)
    if issue_match:
        paragraph(doc, f'Задача №{issue_match[0]}: {REPO}/issues/{issue_match[0]}')
    for source in sources:
        if source == 'LICENSE':
            url = REPO + '/pull/22#issuecomment-5603249401'
        else:
            commit = REPORT if source == MATRIX else BASE
            url = REPO + '/blob/' + commit + '/' + source
        p = paragraph(doc, url)
        for run in p.runs:
            run.font.size = Pt(8)
    paragraph(doc, 'Имена файлов, адреса и формальные обозначения оставлены без перевода, чтобы материал можно было найти однозначно. Техническая успешность отдельной проверки не заменяет остальные решения о приёмке.')
    footer = section.footer.paragraphs[0]
    footer.text = f'Решение {index:02d}  •  '
    field = OxmlElement('w:fldSimple')
    field.set(qn('w:instr'), 'PAGE')
    footer._p.append(field)
    doc.core_properties.title = title
    doc.core_properties.subject = 'Пояснение для независимой приёмки; не принятое решение'
    doc.core_properties.language = 'ru-RU'
    path = HERE / f'{index:02d}_{title.replace(" ", "_")}.docx'
    doc.save(path)
    return path


# Decision adopted by the user on 2026-09-10; implementation evidence is separate.
THRESHOLD_DECISION = "Обязательно исправить преобразователь: при точном равенстве порогу выбирать худший соседний класс. Перенос восьми расхождений на будущую работу исключён. Непосредственное задание классов не заменяет исправление."
for _i in range(1, 5):
    _row = list(DATA[_i])
    _row[4] = [THRESHOLD_DECISION]
    _row[5] = "Исправление выполнено в src/uppaal_mcp/phy/alpha.py. Результаты программной проверки приведены в threshold-correction/check-results.json и журналах рядом с ним. По поручению пользователя привязка обновлена до точной новой контрольной суммы. Повторный полный набор программных проверок завершён успешно; журналы и точная версия сохранены в threshold-correction/pin-update. Модель и формулы совпадают с прежними по контрольным суммам. Старые и посторонние изменения преобразователя отклоняются. Независимая приёмка исправления и прохождение Gate 1 не заявляются."
    _row[6] = ["Проверить восемь порогов снизу, на границе и сверху: 24 случая.", "Проверить категории внутри интервалов и отдельно заданный предел возраста.", "Сверить версию кода и журналы; записать заключение назначенного проверяющего."]
    _row[7] = "Решение пользователя от 10.09.2026: " + THRESHOLD_DECISION + " Заключение проверяющего о выполнении: ____."
    DATA[_i] = tuple(_row)
_row = list(DATA[3])
_row[3] = "В прежнем преобразователе восемь порогов относили равенство к лучшему классу вопреки заявленному правилу. Исправлены пороги SINR_c: 0, 10, 25; Pd: 0.5, 0.9; Rfa: 0.05, 0.2; AoS_CTRL: 10. На границе выбираются соответственно OUTAGE, LOW, OK; FAILED, LOW; HIGH, CRITICAL; EXPIRED. Физическая калибровка и обработка отсутствующих измерений этим исправлением не подтверждаются."
DATA[3] = tuple(_row)

def main():
    files = [make(i, item) for i, item in enumerate(DATA, 1)]
    order = 'Порядок рассмотрения решений\n\n' + '\n'.join(f'{i:02d}. {item[0]} — задача ' + ('№' if item[1][0].isdigit() else '') + item[1] for i,item in enumerate(DATA,1))
    order += '\n\nВ каждом документе рассматривается один вопрос. Заключение заполняет принимающий специалист. Ни один документ не является заранее данным одобрением.\n'
    (HERE / 'Порядок_рассмотрения.txt').write_text(order, encoding='utf-8')
    with zipfile.ZipFile(HERE / 'Решения_для_приёмки_18_документов.zip', 'w', zipfile.ZIP_DEFLATED) as z:
        for p in files + [HERE / 'Порядок_рассмотрения.txt']:
            z.write(p, p.name)
    index = {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in files}
    (HERE / 'document-hashes.json').write_text(json.dumps(index, indent=2, ensure_ascii=False)+'\n', encoding='utf-8')
    print(f'Created {len(files)} documents and ZIP')


if __name__ == '__main__':
    main()
